import os

def is_valid_image(filepath):
    """Check if an image file is valid by trying to open it with PIL"""
    try:
        with PIL.Image.open(filepath) as img:
            img.verify()
        return True
    except:
        return False

# Get all class directories
class_dirs = [d for d in data_dir.iterdir() if d.is_dir()]
valid_files = []

# Find all valid image files
for class_dir in class_dirs:
    for img_file in class_dir.glob('*.jpg'):
        if is_valid_image(img_file):
            valid_files.append(img_file)

print(f"Found {len(valid_files)} valid images out of {len(list(data_dir.glob('*/*.jpg')))} total files")

# Create a new directory with only valid images
import shutil
temp_dir = pathlib.Path('/tmp/valid_images')
if temp_dir.exists():
    shutil.rmtree(temp_dir)
temp_dir.mkdir()

for class_dir in class_dirs:
    new_class_dir = temp_dir / class_dir.name
    new_class_dir.mkdir()
    for img_file in class_dir.glob('*.jpg'):
        if is_valid_image(img_file):
            shutil.copy(img_file, new_class_dir / img_file.name)

train_ds = tf.keras.utils.image_dataset_from_directory(
