# Define a function to filter out corrupted images
def filter_valid_images(image, label):
    """Filter function - passes through valid images"""
    # This function will be applied to each image-label pair
    # If the image is corrupted, it will raise an error which will be caught
    return True

# Create a dataset wrapper to handle corrupted data
def create_safe_dataset(dataset):
    """Create a dataset that skips corrupted images"""
    def decode_and_process(img, label):
        try:
            # Rescale the image
            img = normalization_layer(img)
            return img, label
        except:
            # Skip this sample if processing fails
            raise tf.errors.InvalidArgumentError(None, None, "Corrupted image")

    return dataset.map(
        lambda x, y: decode_and_process(x, y),
        num_parallel_calls=tf.data.AUTOTUNE
    )"}

